query:
// 1. Create a Patient Node
CREATE (p:Patient {
  patientID: "P001",
  age_group: "older_low_tech_utilizer",
  gender: "M"
})
RETURN p;

// 2. Create a Staff Node
CREATE (s:Staff {
  staffID: "S001",
  role: "Nurse",
  department: "Emergency"
})
RETURN s;

// 3. Create a Process_Activity Node
CREATE (a:Process_Activity {
  activityID: "A001",
  name: "Triage",
  type: "Clinical"
})
RETURN a;

// 4. Create a Technology_System Node
CREATE (t:Technology_System {
  systemID: "T001",
  name: "Electronic_Health_Record (EHR)",
  type: "Software"
})
RETURN t;

// 5. Create a Feedback_Comment Node
CREATE (f:Feedback_Comment {
  commentID: "F001",
  source: "Google_Reviews",
  overall_sentiment: "negative"
})
RETURN f;

// 6. Create an Issue Node
CREATE (i:Issue {
  issueID: "I001",
  description: "Long wait time",
  category: "Procedures_Standards"
})
RETURN i;

// 7. Create a Recommendation Node
CREATE (r:Recommendation {
  recommendationID: "R001",
  description: "Implement a digital queue system",
  priority: "High"
})
RETURN r;

// 8. Create a Location Node
CREATE (l:Location {
  locationID: "L001",
  name: "Waiting_Room"
})
RETURN l;

// 9. Create an EMPI_Record Node
CREATE (e:EMPI_Record {
  empiID: "E001",
  patient_record_link: "HIS_12345"
})
RETURN e;

// 1. Patient HAS_EMPI Record
MATCH (p:Patient {patientID: "P001"}), (e:EMPI_Record {empiID: "E001"})
CREATE (p)-[:HAS_EMPI]->(e);

// 2. Patient UNDERGOES a Process
MATCH (p:Patient {patientID: "P001"}), (a:Process_Activity {activityID: "A001"})
CREATE (p)-[:UNDERGOES]->(a);

// 3. Patient GIVES_FEEDBACK
MATCH (p:Patient {patientID: "P001"}), (f:Feedback_Comment {commentID: "F001"})
CREATE (p)-[:GIVES_FEEDBACK]->(f);

// 4. Patient EXPERIENCES an Issue
MATCH (p:Patient {patientID: "P001"}), (i:Issue {issueID: "I001"})
CREATE (p)-[:EXPERIENCES]->(i);

// 6. Staff USES a Technology System
MATCH (s:Staff {staffID: "S001"}), (t:Technology_System {systemID: "T001"})
CREATE (s)-[:USES]->(t);

// 5. Staff PERFORMS a Process
MATCH (s:Staff {staffID: "S001"}), (a:Process_Activity {activityID: "A001"})
CREATE (s)-[:PERFORMS]->(a);

// 7. Process USES_TECH Technology
MATCH (a:Process_Activity {activityID: "A001"}), (t:Technology_System {systemID: "T001"})
CREATE (a)-[:USES_TECH]->(t);

// 8. Process CAUSES an Issue
MATCH (a:Process_Activity {activityID: "A001"}), (i:Issue {issueID: "I001"})
CREATE (a)-[:CAUSES]->(i);

// 9. Issue ADDRESSED_BY a Recommendation
MATCH (i:Issue {issueID: "I001"}), (r:Recommendation {recommendationID: "R001"})
CREATE (i)-[:ADDRESSED_BY]->(r);

// 10. Staff WORKS_IN a Location (Let's create a new Staff and Location for this)
MATCH (s:Staff {staffID: "S001"}), (l:Location {locationID: "L001"})
CREATE (s)-[:WORKS_IN]->(l);

// 11. Process OCCURS_IN a Location
MATCH (a:Process_Activity {activityID: "A001"}), (l:Location {locationID: "L001"})
CREATE (a)-[:OCCURS_IN]->(l);

// 12. Technology_System RELATED_TO an Issue (Let's create a new Issue for this)
MATCH (t:Technology_System {systemID: "T001"}), (i:Issue {issueID: "I001"})
CREATE (t)-[:RELATED_TO]->(i);

// Create uniqueness constraints for all primary keys
// This ensures all patientIDs are unique and creates an index for speed
CREATE CONSTRAINT patient_id IF NOT EXISTS FOR (p:Patient) REQUIRE p.patientID IS UNIQUE;
CREATE CONSTRAINT staff_id IF NOT EXISTS FOR (s:Staff) REQUIRE s.staffID IS UNIQUE;
CREATE CONSTRAINT activity_id IF NOT EXISTS FOR (a:Process_Activity) REQUIRE a.activityID IS UNIQUE;
CREATE CONSTRAINT system_id IF NOT EXISTS FOR (t:Technology_System) REQUIRE t.systemID IS UNIQUE;
CREATE CONSTRAINT issue_id IF NOT EXISTS FOR (i:Issue) REQUIRE i.issueID IS UNIQUE;
CREATE CONSTRAINT comment_id IF NOT EXISTS FOR (f:Feedback_Comment) REQUIRE f.commentID IS UNIQUE;
CREATE CONSTRAINT recommendation_id IF NOT EXISTS FOR (r:Recommendation) REQUIRE r.recommendationID IS UNIQUE;
CREATE CONSTRAINT location_id IF NOT EXISTS FOR (l:Location) REQUIRE l.locationID IS UNIQUE;
CREATE CONSTRAINT empi_id IF NOT EXISTS FOR (e:EMPI_Record) REQUIRE e.empiID IS UNIQUE;

MATCH (p:Patient)-[:UNDERGOES]->(pa:Process_Activity)
RETURN p.patientID, pa.name AS Activity, pa.type
LIMIT 10;

CREATE (newPatient:Patient {
  patientID: "P100",
  age_group: "younger_high_tech_utilizer", 
  gender: "F",
  overall_satisfaction_score: 4.5
})
WITH newPatient
MATCH (pa:Process_Activity {name: "Triage"})
CREATE (newPatient)-[:UNDERGOES]->(pa);

MATCH (t:Technology_System {name: "Electronic_Health_Record (EHR)"})
SET t.usability_score = 4.2
RETURN t.name, t.usability_score;
